-- The dashboard's catalog (generated by tests/tools/gift-items <save> catalog from PKHeX's Let's Go data): the
-- giftable items (models.GIFTABLE), the Let's Go Pokemon and moves, names in English. Reference data only.
CREATE TABLE catalog_items (id INTEGER PRIMARY KEY, name TEXT NOT NULL, pocket TEXT NOT NULL);
CREATE TABLE catalog_species (id INTEGER PRIMARY KEY, name TEXT NOT NULL, alolan BOOLEAN NOT NULL);
CREATE TABLE catalog_moves (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
